"""The generated command-line reference (specification §12.1, §12.2):
``docs/cubeproof/cli-reference.md``.

``python -m cubeproof.cli.reference`` prints the document from the table of
:mod:`cubeproof.cli.spec`; a test regenerates it and compares it with the file in the repository,
so the reference is exactly the parser's contract. Nothing is edited by hand.
"""

from __future__ import annotations

import sys

from cubeproof.cli.spec import COMMANDS, EXIT_MEANING, Arg, Command

__all__ = ["main", "render_reference"]

HEADER = (
    "<!-- Generated by `python -m cubeproof.cli.reference` from `cubeproof/cli/spec.py`; "
    "do not edit. -->"
)


def _value(arg: Arg, separator: str = "|") -> str:
    if arg.kind == "flag":
        return ""
    if arg.choices:
        return separator.join(arg.choices)
    if arg.metavar is not None:
        return arg.metavar
    return {"path": "PATH", "int": "N", "float": "NUMBER", "str": "TEXT"}[arg.kind]


def _usage(arg: Arg) -> str:
    if arg.positional:
        return _value(arg)
    flag = "-o" if arg.flags[0] == "-o" else arg.flags[-1]
    text = flag if arg.kind == "flag" else f"{flag} {_value(arg)}"
    if arg.many:
        text += " ..."
    if arg.repeat:
        text = f"{text} [{text}]..." if arg.required else f"[{text}]..."
    elif not arg.required and not arg.positional:
        text = f"[{text}]"
    return text


def _synopsis(command: Command) -> str:
    parts = ["cubeproof", *command.words, *(_usage(a) for a in command.args)]
    return " ".join(parts)


def _default(arg: Arg) -> str:
    if arg.kind == "flag" or arg.default is None:
        return ""
    return f"`{arg.default}`"


def _row(arg: Arg) -> str:
    names = ", ".join(f"`{flag}`" for flag in arg.flags)
    value = _value(arg, "/")
    cells = (
        names,
        f"`{value}`" if value else "",
        "yes" if arg.required or arg.positional else "no",
        _default(arg),
        arg.help + (" (repeatable)" if arg.repeat else ""),
    )
    return "| " + " | ".join(cells) + " |"


def _section(command: Command) -> list[str]:
    lines = [
        f"## `cubeproof {command.name}`",
        "",
        command.summary[0].upper() + command.summary[1:] + ".",
        "",
    ]
    if not command.available:
        lines += ["**Not available in this build:** it parses its arguments and exits with 3.", ""]
    lines += ["```text", _synopsis(command), "```", ""]
    if command.args:
        lines += [
            "| Argument | Value | Required | Default | Meaning |",
            "|---|---|---|---|---|",
            *(_row(a) for a in command.args),
            "",
        ]
    if command.output:
        lines += [f"Standard output: {command.output}.", ""]
    if command.rules:
        lines += ["Rules:", "", *(f"- {rule}." for rule in command.rules), ""]
    if command.exits:
        lines += [
            "| Exit | Meaning here |",
            "|---|---|",
            *(f"| {code} | {meaning} |" for code, meaning in command.exits),
            "",
        ]
    return lines


def render_reference() -> str:
    """The whole reference as Markdown text (LF line ends, one final newline)."""
    lines = [
        "# cubeproof command line reference",
        "",
        HEADER,
        "",
        "Every command is `cubeproof COMMAND ...` (or `python -m cubeproof COMMAND ...`). A usage "
        "error, an unknown option or an invalid combination of options exits with 3 before any "
        "work. Result documents are written to standard output; notes, errors "
        "(`cubeproof: error [rule] detail`) and the run log are written to standard error. "
        "`cubeproof --version` prints `cubeproof VERSION` and exits with 0; `-h` after the "
        "program or any command prints its help.",
        "",
        "## Exit codes",
        "",
        "| Code | Meaning |",
        "|---|---|",
        *(f"| {code} | {meaning} |" for code, meaning in EXIT_MEANING.items()),
        "",
        "For completed work the conditions have the priority 4 > 5 > 2 > 6 > 1 > 0; an "
        "interruption exits with 130 unless an integrity error had already been diagnosed (4). "
        "Preflight errors return before any work.",
        "",
    ]
    for command in COMMANDS:
        if not command.hidden:
            lines += _section(command)
    return "\n".join(lines).rstrip("\n") + "\n"


def main() -> int:
    """Print the reference (the only output of this module)."""
    sys.stdout.write(render_reference())
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
